const referenceBeforeRetouch=sceneReference;
sceneReference=function(scene,key){if(scene.editIntent!=='retouch')return referenceBeforeRetouch(scene,key);const versions=(scene.sceneVersions||[]).filter(v=>v.image_url&&(v.view_key||'master')===key);const version=versions.find(v=>v.id===scene.retouchJobId);return{scene,version,required:true,reason:'请选择一张本场景已有成图作为微调参考。'};};
const renderBeforeRetouch=renderScenes;
renderScenes=function(){renderBeforeRetouch();const scene=currentScene();if(!scene)return;const generate=document.querySelector('#sceneGenerate');const wrap=document.createElement('div');wrap.style.cssText='margin:12px 0;padding:12px;border:1px solid #344254;border-radius:8px';const label=document.createElement('label');label.textContent='本次操作';const select=document.createElement('select');select.setAttribute('aria-label','本次操作');for(const [value,text] of [['build','建立场景 / 改变机位'],['retouch','微调已有成图 · 保持构图']]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option)}select.value=scene.editIntent||'build';select.onchange=()=>{scene.editIntent=select.value;save();render()};label.append(select);wrap.append(label);if(scene.editIntent==='retouch'){const view=scene.activeView||'master',versions=(scene.sceneVersions||[]).filter(v=>v.image_url&&(v.view_key||'master')===view);const baseLabel=document.createElement('label');baseLabel.textContent='选择要微调的成图';const base=document.createElement('select');base.setAttribute('aria-label','选择要微调的成图');const empty=document.createElement('option');empty.value='';empty.textContent='请选择满意构图的版本';base.append(empty);versions.forEach((v,i)=>{const option=document.createElement('option');option.value=v.id;option.textContent='V'+(i+1)+' · '+new Date(v.created_at||v.finished_at).toLocaleString('zh-CN');base.append(option)});base.value=scene.retouchJobId||'';base.onchange=()=>{scene.retouchJobId=base.value;save();render()};baseLabel.append(base);wrap.append(baseLabel);const note=document.createElement('p');note.className='subtle';note.textContent='仅发送你填写的修改提示词，不追加共享世界色彩、广角或移动机位指令。参考图固定为所选版本，生成后不会自动换成新图。';wrap.append(note);document.querySelector('#sceneReferencePreview label')?.remove();}generate.before(wrap);};render();
